'use strict';
const QB=window.QUIZ_DATA;
let quizAttempts={},retryIds=null,quizRows=[];
try{const saved=JSON.parse(localStorage.getItem('pcb-quiz-attempts-v1')||'{}');if(saved&&typeof saved==='object'&&!Array.isArray(saved))for(const q of QB.questions){const a=saved[q.id];if(a&&Number.isInteger(a.choice)&&a.choice>=0&&a.choice<4)quizAttempts[q.id]={choice:a.choice};}}catch{}
function saveQuiz(){try{localStorage.setItem('pcb-quiz-attempts-v1',JSON.stringify(quizAttempts));$('save-status').textContent='Attempts saved in this browser.'}catch{$('save-status').textContent='Browser storage unavailable: keep this tab open to retain this session.'}}
function quizCard(q){
 const a=quizAttempts[q.id],answered=!!a,correct=answered&&a.choice===q.answer;
 return `<article class="card quiz-card" id="${q.id}"><div class="card-top"><span class="pill">${q.ref.year}${q.ref.year===2022?' · Term II':''}</span><span class="muted">Set ${esc(q.ref.set)} · Q${esc(q.ref.number)} · 1 practice point</span></div><p class="small muted">${esc(q.kind)}</p><h2 id="${q.id}-prompt">${esc(q.prompt)}</h2><div class="quiz-options" role="group" aria-labelledby="${q.id}-prompt">${q.options.map((o,i)=>`<button class="quiz-option ${answered?(i===q.answer?'correct':i===a.choice?'incorrect':''):''}" data-quiz-id="${q.id}" data-choice="${i}" aria-pressed="${answered&&a.choice===i}" ${answered?'disabled':''}><span class="option-letter">${String.fromCharCode(65+i)}</span><span>${esc(o)}</span>${answered&&i===q.answer?'<strong>✓ Correct answer</strong>':answered&&i===a.choice?'<strong>✕ Your answer</strong>':''}</button>`).join('')}</div><div class="quiz-feedback" aria-live="polite">${answered?`<div class="feedback ${correct?'good':'bad'}"><strong>${correct?'Correct · +1 point':'Incorrect · 0 points'}</strong><p>${esc(q.explanation)}</p></div>`:'<p class="small muted">Choose once to check your answer. No negative marking.</p>'}</div>${sourceDetails(q.ref)}${q.workedId?`<button class="text-button" data-worked="${esc(q.workedId)}">Open the written-answer version →</button>`:''}</article>`;
}
function getQuizRows(){
 const query=$('search').value.trim().toLowerCase(),year=$('year').value;
 return QB.questions.filter(q=>chapterOf(q.chapter).subject===subject&&(query||q.chapter===chapter)&&(!year||q.ref.year===+year)&&(`${q.prompt} ${q.options.join(' ')} ${q.explanation} ${q.ref.set} ${chapterOf(q.chapter).title}`).toLowerCase().includes(query)&&(!retryIds||retryIds.has(q.id)));
}
function quizScore(){
 const answered=quizRows.filter(q=>quizAttempts[q.id]),correct=answered.filter(q=>quizAttempts[q.id].choice===q.answer).length,wrong=answered.length-correct;
 $('quiz-score').innerHTML=`<div class="score-numbers"><div><b>${correct}/${quizRows.length}</b><span>points in this selection</span></div><div><b>${answered.length}</b><span>answered</span></div><div><b>${wrong}</b><span>incorrect</span></div><div><b>${quizRows.length-answered.length}</b><span>remaining</span></div></div><div class="score-actions"><button id="retry-quiz" ${wrong?'':'disabled'}>Retry ${wrong} mistake${wrong===1?'':'s'}</button><button id="reset-quiz" ${answered.length?'':'disabled'}>Reset this selection</button>${retryIds?'<button id="exit-retry">Show all questions</button>':''}</div><p class="small muted">1 point per correct answer; 0 for wrong or unattempted. Scores reflect the current attempt, including retries—not a board-exam mark or rank prediction. <span id="save-status">Attempts stay in this browser.</span></p>`;
 $('retry-quiz').onclick=()=>{retryIds=new Set(quizRows.filter(q=>quizAttempts[q.id]&&quizAttempts[q.id].choice!==q.answer).map(q=>q.id));for(const id of retryIds)delete quizAttempts[id];render();saveQuiz()};
 $('reset-quiz').onclick=()=>{for(const q of quizRows)delete quizAttempts[q.id];render();saveQuiz()};
 if($('exit-retry'))$('exit-retry').onclick=()=>{retryIds=null;render()};
}
function renderQuiz(){
 quizRows=getQuizRows();
 $('chapter-description').textContent=`${QB.questions.filter(q=>q.chapter===chapter).length} quiz questions in this chapter. Choose an option to check your answer and earn a practice point.`;
 $('count').textContent=`${quizRows.length} quiz questions${retryIds?' · retrying mistakes':''}${$('search').value.trim()?' across '+subject:''}`;
 $('results').innerHTML=`<section class="quiz-score" id="quiz-score" aria-label="Quiz score" aria-live="polite"></section><div id="quiz-cards">${quizRows.length?quizRows.map(quizCard).join(''):'<div class="empty">No quiz-ready questions match these filters yet. Choose All years, clear search, or use the paper catalogue to find original sets.</div>'}</div>`;
 quizScore();
}
function paperCatalogue(){
 screen='papers';nav();$('overview').hidden=true;$('study').hidden=true;$('sources-panel').hidden=false;
 $('sources-panel').innerHTML=`<div class="eyebrow">2024 · 2025 · 2026 / MAIN EXAMS</div><h1>All-set paper catalogue</h1><p>${esc(QB.coverage)}</p><div class="note"><strong>${QB.papers.length} PDF files catalogued · ${QB.questions.length} quiz questions ready across all years.</strong> Download the official subject archive and open the exact filename below. A zero quiz count means that paper has not yet been converted into scored practice. No unchecked OCR questions are scored.</div><div class="catalog-filters"><label>Subject <select id="paper-subject"><option value="">All subjects</option>${['Physics','Chemistry','Biology'].map(s=>`<option>${s}</option>`).join('')}</select></label><label>Year <select id="paper-year"><option value="">All three years</option>${[2026,2025,2024].map(y=>`<option>${y}</option>`).join('')}</select></label><label>Set or filename <input id="paper-search" type="search" placeholder="e.g. 55/2/1"></label></div><p id="paper-count" role="status"></p><div class="table-wrap"><table><thead><tr><th>Year / subject</th><th>Set / exact PDF filename</th><th>Quiz-ready selections</th><th>Official archive</th></tr></thead><tbody id="paper-rows"></tbody></table></div><p class="small muted">Counts refer to authored practice selections, not complete papers or all original subparts. Special versions and duplicate scan/text versions are retained by their archive filenames; file counts are not distinct-set counts. Original papers and diagrams remain in CBSE’s archives.</p>`;
 function update(){const s=$('paper-subject').value,y=$('paper-year').value,t=$('paper-search').value.toLowerCase();const rows=QB.papers.filter(p=>(!s||p.subject===s)&&(!y||p.year===+y)&&(`${p.set} ${p.file}`).toLowerCase().includes(t));$('paper-count').textContent=`${rows.length} paper files`;$('paper-rows').innerHTML=rows.map(p=>`<tr><td>${p.year}<br>${p.subject}</td><td>${esc(p.set)}<br><small>${esc(p.file)}</small></td><td>${p.quizCount}${p.quizCount?' selections':' · not converted'}</td><td><a href="${esc(p.url)}" target="_blank" rel="noopener">Download ${p.subject} archive</a></td></tr>`).join('')}
 for(const id of ['paper-subject','paper-year','paper-search'])$(id).addEventListener(id==='paper-search'?'input':'change',update);update();
}
$('results').addEventListener('click',e=>{
 const b=e.target.closest('[data-quiz-id]');
 if(b){const q=QB.questions.find(x=>x.id===b.dataset.quizId);if(!q||quizAttempts[q.id])return;const choice=Number(b.dataset.choice);if(!Number.isInteger(choice)||choice<0||choice>3)return;quizAttempts[q.id]={choice};const card=b.closest('article');card.outerHTML=quizCard(q);quizScore();saveQuiz();document.getElementById(q.id).querySelector('.quiz-feedback').setAttribute('tabindex','-1');document.getElementById(q.id).querySelector('.quiz-feedback').focus({preventScroll:true});return}
 const w=e.target.closest('[data-worked]');if(w){const q=D.questions.find(x=>x.id===w.dataset.worked);if(!q)return;chapter=q.chapter;subject=chapterOf(chapter).subject;$('search').value='';$('year').value='';$('mode').value='questions';retryIds=null;render();const el=document.getElementById(q.id);el.querySelector('details.solution').open=true;el.scrollIntoView({behavior:'smooth',block:'start'})}
});
$('papers-toggle').addEventListener('click',paperCatalogue);
